args.sql:
UPDATE joint_performance 
SET joint_metrics = (
    SELECT jsonb_set(
        jsonb_set(joint_metrics, '{J2,speed_dps}', ROUND((joint_metrics->'J2'->>'speed_dps')::numeric * 0.9, 2)::text::jsonb),
        '{J2,torque_nm}',
        ROUND((joint_metrics->'J2'->>'torque_nm')::numeric * 0.85, 2)::text::jsonb
    )
)
WHERE jperfdetref IN (
    SELECT rd.botdetreg FROM robot_details rd WHERE rd.modelseriesval = 'Series_784'
);
